using System.Windows;
using System.Windows.Controls;
namespace DomainBridge.Desktop; public partial class MainWindow : Window { private static readonly Dictionary<string,(string Primary,string Detail)> Modules = new() { ["Parc"]=("Aucun poste remonté pour le moment.","Installez l’agent pour alimenter l’inventaire matériel, Windows et logiciels."), ["Collections"]=("Créez des collections dynamiques.","Ciblez les postes par domaine, OU, site, version Windows ou conformité."), ["Déploiements"]=("Préparez un déploiement approuvé.","Packages, WinGet et tâches de maintenance seront exécutés par vagues avec suivi par poste."), ["Bibliothèque"]=("Bibliothèque technicien.","Diagnostics réseau, GPO, Defender et Windows Update seront proposés comme actions signées."), ["Historique"]=("Aucune opération enregistrée.","Chaque inventaire, déploiement, approbation et rollback sera conservé dans PostgreSQL."), ["Paramètres"]=("Configurez l’environnement on-premise.","API, PostgreSQL, PKI, AD local et Entra ID sont définis après installation, sans secret dans le produit.") }; public MainWindow()=>InitializeComponent(); private void Navigation_SelectionChanged(object s, SelectionChangedEventArgs e) { if(Navigation.SelectedItem is not ListBoxItem i)return; var section=i.Content?.ToString()??"Parc"; SectionTitle.Text=section; var migration=section=="Migration"; MigrationWorkspace.Visibility=migration?Visibility.Visible:Visibility.Collapsed; if(migration){PrimaryMessage.Text="Préparez une migration contrôlée de domaine A vers domaine B."; SecondaryMessage.Text="Le plan pilote collecte les prérequis et génère les étapes d’exécution et de rollback.";} else {var module=Modules[section]; PrimaryMessage.Text=module.Primary; SecondaryMessage.Text=module.Detail;} } private void CreatePilotPlan_Click(object s, RoutedEventArgs e)=>MigrationStatus.Text="Plan pilote créé : découverte → prérequis → approbation → vague pilote → validation → rollback si nécessaire."; private void CheckPrerequisites_Click(object s, RoutedEventArgs e)=>MigrationStatus.Text="Prérequis à raccorder : inventaire agent, DNS/DC, PKI, profils, espace disque, BitLocker et audit PostgreSQL."; }
